const requested = parseInt(query, 10);

if (isNaN(requested) || requested <= 0) {
  return JSON.stringify({
    allowed: false,
    limit: 10,
    message: "The requested number must be a positive integer."
  });
}

const approved = Math.min(requested, 10);

return JSON.stringify({
  allowed: true,
  requested: requested,
  approved: approved,
  limit: 10,
  limited: requested > 10
});
